//! The same Markdown read the same way as the main screen's renderer: cases.rs holds what md.js made of each case
//! (generated by running it, see there), in a plain form both sides can write.

use super::*;
use alloc::format;
use alloc::string::ToString;

#[path = "cases.rs"]
mod cases;

fn q(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '|' => out.push_str("\\|"),
            ' ' => out.push_str("\\_"),
            '[' => out.push_str("\\["),
            ']' => out.push_str("\\]"),
            ';' => out.push_str("\\;"),
            ',' => out.push_str("\\,"),
            '/' => out.push_str("\\/"),
            c => out.push(c),
        }
    }
    out
}

fn runs(spans: &[Span]) -> String {
    spans.iter().map(|s| format!("{}:{}", s.style, q(&s.text))).collect::<Vec<_>>().join(" ")
}

fn plain(blocks: &[Block]) -> Vec<String> {
    blocks
        .iter()
        .map(|b| match b {
            Block::Para(spans) => format!("P {}", runs(spans)),
            Block::Heading(level, spans) => format!("H{level} {}", runs(spans)),
            Block::Code(text) => format!("C {}", q(text)),
            Block::Rule => "HR".to_string(),
            Block::Quote(inner) => format!("Q[{}]", plain(inner).join(";")),
            Block::List { ordered, start, items } => {
                let items: Vec<String> = items
                    .iter()
                    .map(|it| {
                        let task = match it.task {
                            Some(true) => "T1 ",
                            Some(false) => "T0 ",
                            None => "",
                        };
                        format!("{task}{}", runs(&it.spans))
                    })
                    .collect();
                format!("L{}{} [{}]", if *ordered { "o" } else { "u" }, start, items.join(","))
            }
            Block::Table { head, rows } => {
                let head: Vec<String> = head.iter().map(|c| runs(c)).collect();
                let rows: Vec<String> = rows.iter().map(|r| r.iter().map(|c| runs(c)).collect::<Vec<_>>().join("|")).collect();
                format!("T [{}] [{}]", head.join("|"), rows.join("/"))
            }
        })
        .collect()
}

#[test]
fn reads_markdown_as_the_main_screen_does() {
    let mut wrong = Vec::new();
    for (md, expected) in cases::CASES {
        let got = plain(&parse(md)).join("\n");
        if got != *expected {
            wrong.push(format!("{md:?}\n  md.js: {expected}\n  here:  {got}"));
        }
    }
    assert!(wrong.is_empty(), "{} of {} differ:\n{}", wrong.len(), cases::CASES.len(), wrong.join("\n"));
}

#[test]
fn styles_nest() {
    assert_eq!(
        inline("**a [b `c`](u) ~~d~~**"),
        [
            Span { text: "a ".into(), style: BOLD },
            Span { text: "b ".into(), style: BOLD | LINK },
            Span { text: "c".into(), style: BOLD | LINK | CODE },
            Span { text: " ".into(), style: BOLD },
            Span { text: "d".into(), style: BOLD | STRUCK },
        ]
    );
    assert_eq!(parse(""), []);
    assert_eq!(parse("\r\n\r\n"), []);
}
